def _icon_class(v: str) -> str:
    if v == "거래완료":
        return "status_icon_close"
    return "status_icon_g" if v in ("A급", "B급", "C급", "네고X") else "status_icon_s"


def thumb_url(pid: str) -> str:
    p = pid.zfill(9)  # 사이트처럼 글번호를 세 자리씩 거꾸로 나눈 경로
    return f"{IMG}/files/thumbnails/{p[6:9]}/{p[3:6]}/{p[0:3]}/150x100.crop.jpg?t=1"


