def render_card(c: dict) -> str:
    icons = "\n".join(f'<span class="status_icon {_icon_class(v)}">{esc(v)}</span>' for v in c["icons"])
    if c["price"] is None:  # 거래완료 카드: 첫 줄에 상태 아이콘만, 가격 줄 없음
        price_row, icon_row = icons, ""
    else:
        price_row = f'<span style="font-size:16px;font-weight:500;color:#ff8c8c">{c["price"]:,}원</span>'
        icon_row = icons
    update = '<span class="update-icon"></span> ' if c["bumped"] else ""
    return f"""<div class="item">
<div class="item__left">
{AD_BLOCK if c["ad"] else ""}<a class="item__container clearfix" href="/ski_sell2/{c["id"]}">
<div class="item__thumbnail">
<img src="{thumb_url(c["id"])}"/>
</div>
<div class="item__contents">
<div class="item__inner item__subject">
<span class="icons">
{update}</span>
<span class="subject">{esc(c["title"])}</span>
</div>
<div class="item__inner item__etc-wrp">
{price_row}
</div>
<div class="item__inner item__etc-wrp">
{icon_row}{chr(10) if icon_row else ""}</div>
<div class="item__inner item__etc-wrp">
<div class="item__author"><span>{esc(c["author"])}</span></div> <div class="item__date"><span>{c["ago"]}</span></div> \
<div>조회: <span>{c["views"]}</span></div> <div>댓글: <span>{c["comments"]}</span></div> </div>
</div>
</a>
</div>
</div>"""


def render_notices() -> str:
    rows = []
    for href, title, color, n_comments in NOTICES:
        right = f'<a class="comment-icon" href="{href}#comment">[{n_comments}]</a> ' if n_comments else ""
        rows.append(f"""<div class="item item-list item-notice">
<div class="item__left">
<div class="item__inner item__subject">
<a class="subject" href="{href}"><span style="font-weight:bold;color:{color}">{esc(title)}</span></a>
</div>
</div>
<div class="item__right">
{right}</div>
</div>""")
    href, title = NOTICE_LINK
